BEGIN TRANSACTION;
CREATE TABLE admin_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id INTEGER,action TEXT NOT NULL,details TEXT DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admins(id INTEGER PRIMARY KEY AUTOINCREMENT,telegram_id INTEGER UNIQUE NOT NULL,role TEXT NOT NULL DEFAULT 'owner',is_active INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO "admins" VALUES(1,7930269399,'owner',1,'2026-09-12 22:24:58');
CREATE TABLE coupon_usages(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL,user_id INTEGER NOT NULL,order_id INTEGER,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE coupons(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,kind TEXT NOT NULL DEFAULT 'percent',value INTEGER NOT NULL DEFAULT 0,max_users INTEGER NOT NULL DEFAULT 0,max_uses_per_user INTEGER NOT NULL DEFAULT 1,expires_at TIMESTAMP,enabled INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE custom_settings(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL DEFAULT 1,min_gb INTEGER NOT NULL DEFAULT 1,max_gb INTEGER NOT NULL DEFAULT 0,price_per_gb INTEGER NOT NULL DEFAULT 0,min_days INTEGER NOT NULL DEFAULT 1,max_days INTEGER NOT NULL DEFAULT 0,price_per_month INTEGER NOT NULL DEFAULT 0,price_limited_unlimited INTEGER NOT NULL DEFAULT 0,price_per_day INTEGER NOT NULL DEFAULT 0,ask_duration INTEGER NOT NULL DEFAULT 1,default_days INTEGER NOT NULL DEFAULT 30,users_enabled INTEGER NOT NULL DEFAULT 0,min_users INTEGER NOT NULL DEFAULT 1,max_users INTEGER NOT NULL DEFAULT 0,price_per_user INTEGER NOT NULL DEFAULT 0);
INSERT INTO "custom_settings" VALUES(1,1,1,0,0,1,0,0,0,0,1,30,0,1,0,0);
CREATE TABLE orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,panel_id INTEGER,product_id INTEGER,kind TEXT NOT NULL DEFAULT 'suggested',total_amount INTEGER NOT NULL DEFAULT 0,wallet_amount INTEGER NOT NULL DEFAULT 0,card_amount INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'awaiting_payment',username TEXT,password TEXT,custom_gb INTEGER DEFAULT 0,custom_days INTEGER DEFAULT 0,custom_users INTEGER DEFAULT 0,target_service_id INTEGER,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,receipt_at TIMESTAMP,approved_at TIMESTAMP,rejected_at TIMESTAMP,auto_approve_at TIMESTAMP,error TEXT,receipt_file_id TEXT,receipt_message_id INTEGER,approved_by INTEGER,rejected_by INTEGER, coupon_code TEXT, discount_amount INTEGER NOT NULL DEFAULT 0);
CREATE TABLE panels(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,url TEXT NOT NULL,username TEXT NOT NULL,password TEXT NOT NULL,access_token TEXT,status TEXT NOT NULL DEFAULT 'unknown',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_methods(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL DEFAULT 'کارت به کارت',kind TEXT NOT NULL DEFAULT 'card_to_card',card_number TEXT NOT NULL DEFAULT '',card_holder TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,auto_approve INTEGER NOT NULL DEFAULT 0,auto_approve_minutes INTEGER NOT NULL DEFAULT 5,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'suggested',data_gb INTEGER NOT NULL DEFAULT 0,days INTEGER NOT NULL DEFAULT 0,max_users INTEGER NOT NULL DEFAULT 0,price INTEGER NOT NULL DEFAULT 0,description TEXT DEFAULT '',capacity INTEGER NOT NULL DEFAULT 0,sold INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reports_config(id INTEGER PRIMARY KEY CHECK(id=1),chat_id INTEGER,enabled INTEGER NOT NULL DEFAULT 0,topics_json TEXT DEFAULT '{}');
INSERT INTO "reports_config" VALUES(1,NULL,0,'{}');
CREATE TABLE services(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER,user_id INTEGER NOT NULL,panel_id INTEGER NOT NULL,product_id INTEGER,username TEXT NOT NULL,password TEXT NOT NULL,pg_admin_id INTEGER,data_limit_bytes INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'active',started_at TIMESTAMP,expires_at TIMESTAMP,suspended_until TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '');
