CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,amount INTEGER NOT NULL,type TEXT NOT NULL,description TEXT DEFAULT '',order_id INTEGER,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_controls(user_id INTEGER PRIMARY KEY,blocked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,telegram_id INTEGER UNIQUE NOT NULL,username TEXT,first_name TEXT,balance INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
